#!/usr/bin/env node
/**
 * slack_api.cjs — minimal Slack Web API client for common workspace operations.
 * No dependencies; requires Node.js 18+ (global fetch, FormData, Blob).
 *
 * Auth: SLACK_TOKEN environment variable, or --token <token> (bot or user token).
 *
 * Usage:
 *   node slack_api.cjs post-message   --channel <name|ID> --text <text> [--thread-ts <ts>] [--reply-broadcast]
 *   node slack_api.cjs reply          --channel <name|ID> --thread-ts <ts> --text <text>
 *   node slack_api.cjs dm             --user <id|@name|real name> --text <text>
 *   node slack_api.cjs history        --channel <ID> [--limit N] [--latest <ts>] [--oldest <ts>] [--json]
 *   node slack_api.cjs list-channels  [--limit N] [--types <types>] [--json]
 *   node slack_api.cjs list-users     [--limit N] [--json]
 *   node slack_api.cjs upload-file    --channel <name|ID> --file <path> [--title <t>] [--initial-comment <c>] [--alt-text <a>]
 *   node slack_api.cjs delete-message --channel <name|ID> --ts <ts>
 *   node slack_api.cjs help
 */
'use strict';

const fs = require('fs');
const path = require('path');

const API_BASE = 'https://slack.com/api/';
const MAX_PAGES = 10; // safety cap for pagination loops
const CONVERSATION_ID_RE = /^[CDG][A-Z0-9]{8,}$/;
const USER_ID_RE = /^[UW][A-Z0-9]{8,}$/;

let token = null;
let jsonOutput = false;

function die(message, code = 1) {
  process.stderr.write(`Error: ${message}\n`);
  process.exit(code);
}

function clamp(n, lo, hi) {
  return Math.min(hi, Math.max(lo, n));
}

function need(flags, name) {
  const value = flags[name];
  if (value === undefined || value === '') die(`Missing required option: --${name}`);
  return value;
}

function parseArgs(argv) {
  const out = { positionals: [], flags: {} };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--json') {
      out.flags.json = true;
      continue;
    }
    if (arg === '--reply-broadcast') {
      out.flags.replyBroadcast = true;
      continue;
    }
    if (arg.startsWith('--')) {
      const key = arg.slice(2);
      const value = argv[i + 1];
      if (value === undefined || value.startsWith('--')) die(`Missing value for --${key}`);
      out.flags[key] = value;
      i++;
    } else {
      out.positionals.push(arg);
    }
  }
  return out;
}

async function slackRequest(methodName, { method = 'POST', params = {} } = {}) {
  const url = new URL(methodName, API_BASE);
  const headers = { Authorization: `Bearer ${token}` };
  let body;
  if (method === 'GET') {
    for (const [k, v] of Object.entries(params)) {
      if (v !== undefined && v !== null && v !== '') url.searchParams.set(k, String(v));
    }
  } else {
    const form = new URLSearchParams();
    for (const [k, v] of Object.entries(params)) {
      if (v !== undefined && v !== null && v !== '') form.set(k, String(v));
    }
    headers['Content-Type'] = 'application/x-www-form-urlencoded';
    body = form.toString();
  }
  const response = await fetch(url, { method, headers, body });
  const data = await response.json().catch(() => ({}));
  if (!data.ok) {
    if (data.error === 'ratelimited') {
      const retryAfter = Number(response.headers.get('Retry-After') || 1);
      die(`Slack rate limit reached; retry after ${retryAfter}s (Retry-After header).`, 2);
    }
    const scopeHint = data.needed ? ` (missing scope: ${data.needed})` : '';
    die(`Slack API error: ${data.error}${scopeHint}`);
  }
  return data;
}

async function paginate(methodName, params, itemKey, maxItems) {
  const items = [];
  let cursor = '';
  for (let page = 0; page < MAX_PAGES && items.length < maxItems; page++) {
    const pageParams = { ...params, limit: String(clamp(Number(params.limit) || 200, 1, 200)) };
    if (cursor) pageParams.cursor = cursor;
    const data = await slackRequest(methodName, { method: 'GET', params: pageParams });
    items.push(...(data[itemKey] || []));
    cursor = (data.response_metadata && data.response_metadata.next_cursor) || '';
    if (!cursor) break;
  }
  return items.slice(0, maxItems);
}

async function resolveChannelId(nameOrId) {
  if (CONVERSATION_ID_RE.test(nameOrId)) return nameOrId;
  const name = nameOrId.replace(/^#/, '');
  const channels = await paginate(
    'conversations.list',
    { types: 'public_channel,private_channel,im,mpim' },
    'channels',
    2000,
  );
  const match = channels.find((c) => c.name === name);
  if (!match) {
    die(
      `Channel not found: ${nameOrId}. Pass a conversation ID (starts with C, D, or G) or a channel the bot can see.`,
    );
  }
  return match.id;
}

async function resolveUserId(nameOrId) {
  const clean = nameOrId.replace(/^@/, '');
  if (USER_ID_RE.test(clean)) return clean;
  const users = await paginate('users.list', {}, 'members', 2000);
  const matches = users.filter(
    (u) =>
      u.id === clean ||
      u.name === clean ||
      u.real_name === clean ||
      (u.profile && u.profile.display_name === clean),
  );
  if (matches.length === 1) return matches[0].id;
  if (matches.length > 1) {
    die(`Ambiguous user "${nameOrId}": matches ${matches.map((u) => u.id).join(', ')}. Pass a user ID.`);
  }
  die(`User not found: ${nameOrId}. Pass a user ID (starts with U or W) or an exact name/display name.`);
}

function summarizeMessage(m) {
  const text = (m.text || '').replace(/\s+/g, ' ').trim().slice(0, 200);
  return `${m.ts} user=${m.user || m.bot_id || '?'} ${text}`;
}

function emit(data, summary) {
  if (jsonOutput) console.log(JSON.stringify(data));
  else console.log(summary);
}

async function cmdPostMessage(flags) {
  const channel = await resolveChannelId(need(flags, 'channel'));
  const params = { channel, text: need(flags, 'text') };
  if (flags['thread-ts']) params.thread_ts = flags['thread-ts'];
  if (flags.replyBroadcast) params.reply_broadcast = 'true';
  const data = await slackRequest('chat.postMessage', { params });
  emit(
    data,
    `Posted message ts=${data.ts} to channel=${data.channel}${params.thread_ts ? ` (thread ${params.thread_ts})` : ''}`,
  );
}

async function cmdReply(flags) {
  flags['thread-ts'] = need(flags, 'thread-ts');
  await cmdPostMessage(flags);
}

async function cmdDm(flags) {
  const userId = await resolveUserId(need(flags, 'user'));
  const text = need(flags, 'text');
  const open = await slackRequest('conversations.open', { params: { users: userId } });
  const channelId = open.channel.id;
  const data = await slackRequest('chat.postMessage', { params: { channel: channelId, text } });
  emit(data, `Sent DM ts=${data.ts} to user=${userId} (channel ${channelId})`);
}

async function cmdHistory(flags) {
  const channel = await resolveChannelId(need(flags, 'channel'));
  const params = { channel, limit: String(clamp(Number(flags.limit) || 20, 1, 200)) };
  if (flags.latest) params.latest = flags.latest;
  if (flags.oldest) params.oldest = flags.oldest;
  const data = await slackRequest('conversations.history', { method: 'GET', params });
  if (jsonOutput) {
    console.log(JSON.stringify(data));
    return;
  }
  const messages = data.messages || [];
  for (const m of messages) console.log(summarizeMessage(m));
  if (!messages.length) console.log('No messages found.');
  else if (data.has_more) console.log('(more messages available; pass a larger --limit or a later --oldest)');
}

async function cmdListChannels(flags) {
  const maxItems = clamp(Number(flags.limit) || 100, 1, 1000);
  const channels = await paginate(
    'conversations.list',
    { types: flags.types || 'public_channel' },
    'channels',
    maxItems,
  );
  if (jsonOutput) {
    console.log(JSON.stringify(channels));
    return;
  }
  for (const c of channels) {
    const tags = [
      c.is_private ? 'private' : 'public',
      c.is_archived ? 'archived' : null,
      c.is_member ? 'member' : null,
    ].filter(Boolean);
    console.log(`${c.id} ${c.name} [${tags.join(', ')}] members=${c.num_members ?? '?'}`);
  }
  console.log(`Total: ${channels.length} channel(s)`);
}

async function cmdListUsers(flags) {
  const maxItems = clamp(Number(flags.limit) || 100, 1, 1000);
  const users = await paginate('users.list', {}, 'members', maxItems);
  if (jsonOutput) {
    console.log(JSON.stringify(users));
    return;
  }
  for (const u of users) {
    const name = u.real_name || u.name || u.id;
    console.log(`${u.id} ${name}${u.is_bot ? ' [bot]' : ''}${u.deleted ? ' [deleted]' : ''}`);
  }
  console.log(`Total: ${users.length} user(s)`);
}

async function cmdUploadFile(flags) {
  const channel = await resolveChannelId(need(flags, 'channel'));
  const filePath = need(flags, 'file');
  let buffer;
  try {
    buffer = fs.readFileSync(filePath);
  } catch (err) {
    die(`Cannot read file ${filePath}: ${err.code === 'ENOENT' ? 'no such file' : err.message}`);
  }
  const filename = path.basename(filePath);
  const requestParams = { filename, length: String(buffer.length) };
  if (flags['alt-text']) requestParams.alt_text = flags['alt-text'];
  const upload = await slackRequest('files.getUploadURLExternal', { params: requestParams });
  const form = new FormData();
  form.append('file', new Blob([buffer]), filename);
  const uploadResponse = await fetch(upload.upload_url, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}` },
    body: form,
  });
  const uploadResult = await uploadResponse.json().catch(() => ({}));
  if (!uploadResponse.ok || uploadResult.ok === false) {
    die(
      `Uploading file content failed: HTTP ${uploadResponse.status}${uploadResult.error ? ` (${uploadResult.error})` : ''}`,
    );
  }
  const completeParams = { file_id: upload.file_id, channel_ids: channel };
  if (flags.title) completeParams.title = flags.title;
  if (flags['initial-comment']) completeParams.initial_comment = flags['initial-comment'];
  const data = await slackRequest('files.completeUploadExternal', { params: completeParams });
  const file = (data.files || [])[0] || {};
  if (jsonOutput) {
    console.log(JSON.stringify(data));
    return;
  }
  const bits = [`Uploaded file id=${file.id || upload.file_id} to channel=${channel}`];
  if (file.title) bits.push(`title=${file.title}`);
  if (file.permalink) bits.push(`permalink=${file.permalink}`);
  console.log(bits.join(' '));
}

async function cmdDeleteMessage(flags) {
  const channel = await resolveChannelId(need(flags, 'channel'));
  const ts = need(flags, 'ts');
  const data = await slackRequest('chat.delete', { params: { channel, ts } });
  emit(data, `Deleted message ts=${ts} from channel=${channel}`);
}

function printHelp() {
  console.log(`slack_api.cjs — Slack Web API client

Usage:
  node slack_api.cjs <command> [options]

Commands:
  post-message   Post a message (or thread reply) to a channel
                 --channel <name|ID> --text <text> [--thread-ts <ts>] [--reply-broadcast]
  reply          Post a reply inside a thread
                 --channel <name|ID> --thread-ts <ts> --text <text>
  dm             Send a direct message to a user
                 --user <id|@name|real name> --text <text>
  history        Read recent messages from a channel
                 --channel <ID> [--limit N] [--latest <ts>] [--oldest <ts>]
  list-channels  List conversations
                 [--limit N] [--types public_channel,private_channel,im,mpim]
  list-users     List workspace users
                 [--limit N]
  upload-file    Upload a file to a channel (new files API flow)
                 --channel <name|ID> --file <path> [--title <t>] [--initial-comment <c>] [--alt-text <a>]
  delete-message Delete a message you posted
                 --channel <name|ID> --ts <ts>

Options:
  --token <token>   Slack token (defaults to $SLACK_TOKEN)
  --json            Print raw JSON instead of a summary

Authentication:
  Set SLACK_TOKEN to a bot or user token with the scopes listed in references/api.md.
`);
}

async function main() {
  const { positionals, flags } = parseArgs(process.argv.slice(2));
  jsonOutput = Boolean(flags.json);
  const command = positionals[0];
  if (!command || command === 'help' || command === '--help' || command === '-h') {
    printHelp();
    return;
  }
  token = flags.token || process.env.SLACK_TOKEN;
  if (!token) die('No Slack token found. Set the SLACK_TOKEN environment variable or pass --token <token>.');

  const commands = {
    'post-message': cmdPostMessage,
    reply: cmdReply,
    dm: cmdDm,
    history: cmdHistory,
    'list-channels': cmdListChannels,
    'list-users': cmdListUsers,
    'upload-file': cmdUploadFile,
    'delete-message': cmdDeleteMessage,
  };
  const handler = commands[command];
  if (!handler) die(`Unknown command: ${command}. Run with 'help' to see usage.`);
  await handler(flags);
}

main().catch((err) => die(err && err.message ? err.message : String(err)));

#!/usr/bin/env node
/**
 * Task-local validation for the slack-api skill, mirroring the official
 * skill-creator validate_skill.cjs checks (frontmatter, hyphen-case name,
 * single-line description <= 1024 chars, no TODO placeholders) plus a check
 * that files referenced from SKILL.md exist and no init example files remain.
 */
'use strict';

const fs = require('fs');
const path = require('path');

function getAllFiles(dir, fileList = []) {
  for (const file of fs.readdirSync(dir)) {
    const name = path.join(dir, file);
    if (fs.statSync(name).isDirectory()) {
      if (!['node_modules', '.git', '__pycache__'].includes(file)) getAllFiles(name, fileList);
    } else {
      fileList.push(name);
    }
  }
  return fileList;
}

function validateSkill(skillPath) {
  if (!fs.existsSync(skillPath) || !fs.statSync(skillPath).isDirectory()) {
    return { valid: false, message: `Path is not a directory: ${skillPath}` };
  }

  const skillMdPath = path.join(skillPath, 'SKILL.md');
  if (!fs.existsSync(skillMdPath)) return { valid: false, message: 'SKILL.md not found' };

  const content = fs.readFileSync(skillMdPath, 'utf8');
  if (!content.startsWith('---')) return { valid: false, message: 'No YAML frontmatter found' };

  const parts = content.split('---');
  if (parts.length < 3) return { valid: false, message: 'Invalid frontmatter format' };

  const frontmatterText = parts[1];
  const nameMatch = frontmatterText.match(/^name:\s*(.+)$/m);
  const descMatch = frontmatterText.match(/^description:\s*(?:'([^']*)'|"([^"]*)"|(.+))$/m);

  if (!nameMatch) return { valid: false, message: 'Missing "name" in frontmatter' };
  if (!descMatch) {
    return { valid: false, message: 'Description must be a single-line string: description: ...' };
  }

  const name = nameMatch[1].trim();
  const description = (
    descMatch[1] !== undefined ? descMatch[1] : descMatch[2] !== undefined ? descMatch[2] : descMatch[3] || ''
  ).trim();

  if (description.includes('\n')) {
    return { valid: false, message: 'Description must be a single line (no newlines)' };
  }
  if (!/^[a-z0-9-]+$/.test(name)) {
    return { valid: false, message: `Name "${name}" should be hyphen-case` };
  }
  if (name !== path.basename(skillPath)) {
    return { valid: false, message: `Folder name "${path.basename(skillPath)}" must match skill name "${name}"` };
  }
  if (description.length > 1024) {
    return { valid: false, message: 'Description is too long (max 1024)' };
  }

  for (const file of getAllFiles(skillPath)) {
    const fileContent = fs.readFileSync(file, 'utf8');
    if (fileContent.includes('TODO:')) {
      return {
        valid: true,
        message: 'Skill has unresolved TODOs',
        warning: `Found unresolved TODO in ${path.relative(skillPath, file)}`,
      };
    }
  }

  // Extra checks: referenced resources exist, no leftover init examples.
  for (const ref of ['scripts/slack_api.cjs', 'references/api.md']) {
    if (!fs.existsSync(path.join(skillPath, ref))) {
      return { valid: false, message: `Missing referenced file: ${ref}` };
    }
  }
  for (const leftover of [
    'scripts/example_script.cjs',
    'references/example_reference.md',
    'assets/example_asset.txt',
  ]) {
    if (fs.existsSync(path.join(skillPath, leftover))) {
      return { valid: false, message: `Remove leftover example file: ${leftover}` };
    }
  }

  return { valid: true, message: 'Skill is valid!' };
}

const args = process.argv.slice(2);
if (args.length !== 1) {
  console.log('Usage: node validate_slack_skill.cjs <skill_directory>');
  process.exit(1);
}

const result = validateSkill(path.resolve(args[0]));
if (result.warning) console.warn(`⚠️  ${result.warning}`);
if (result.valid) {
  console.log(`✅ ${result.message}`);
} else {
  console.error(`❌ ${result.message}`);
  process.exit(1);
}

